def roman_to_int(s):
    if not s or s.lower() != s:
        return None
    numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    for i in range(len(s)):
        if i > 0 and numerals[s[i]] > numerals[s[i - 1]]:
            result += numerals[s[i]] - 2 * numerals[s[i - 1]]
        else:
