def parse_duration(s):
    if not s:
        return None

    parts = s.split()
    seconds = 0

    for part in parts:
        if part.endswith('h'):
            hours = int(part[:-1])
            seconds += hours * 3600
        elif part.endswith('m'):
            minutes = int(part[:-1])
            seconds += minutes * 60
        elif part.endswith('s'):
            seconds += int(part)

    return seconds
